  9	import com.pousada.marealta.persistence.Database;
 10	import com.pousada.marealta.persistence.MessageDao;
 11	import com.pousada.marealta.persistence.ReservationDao;
 12	import com.pousada.marealta.persistence.RoomDao;
 13	import com.pousada.marealta.service.MessageService;
 14	import com.pousada.marealta.service.PricingService;
 15	import com.pousada.marealta.service.ReportService;
 16	import com.pousada.marealta.service.ReservationService;
 17	import com.pousada.marealta.util.GsonConfig;
 18	import com.pousada.marealta.util.JavalinGsonMapper;
 19	import io.javalin.Javalin;
 20	
 21	import java.math.BigDecimal;
 22	
 23	public class Application {
 24	    public static void main(String[] args) throws Exception {
 25	        String portStr = System.getenv("PORT");
 26	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 27	
 28	        Database.init();
 29	
 30	        RoomDao roomDao = new RoomDao(Database.getDataSource());
 31	        ReservationDao reservationDao = new ReservationDao(Database.getDataSource());
 32	        MessageDao messageDao = new MessageDao(Database.getDataSource());
 33	
 34	        MessageService messageService = new MessageService(messageDao, roomDao);
 35	        PricingService pricingService = new PricingService();
 36	        ReservationService reservationService = new ReservationService(reservationDao, roomDao, pricingService, messageService);
 37	        ReportService reportService = new ReportService(reservationDao, roomDao);
 38	
 39	        RoomHandler roomHandler = new RoomHandler(roomDao);
 40	        ReservationHandler reservationHandler = new ReservationHandler(reservationService, messageService);
 41	        MessageHandler messageHandler = new MessageHandler(messageDao);
 42	        ReportHandler reportHandler = new ReportHandler(reportService);
 43	
 44	        initializeRooms(roomDao);
 45	
 46	        Javalin app = Javalin.create(config ->
 47	            config.jsonMapper(new JavalinGsonMapper())
 48	        ).start(port);
 49	
 50	        app.get("/rooms", roomHandler::listRooms);
 51	
 52	        app.post("/reservations", reservationHandler::createReservation);
 53	        app.get("/reservations/{id}", reservationHandler::getReservation);
 54	        app.post("/reservations/{id}/confirmation", reservationHandler::confirmReservation);
 55	        app.post("/reservations/{id}/cancellation", reservationHandler::cancelReservation);
 56	        app.post("/reservations/{id}/check-in", reservationHandler::checkIn);
 57	        app.post("/reservations/{id}/check-out", ctx -> {
 58	            ctx.attribute("roomDao", roomDao);
 59	            reservationHandler.checkOut(ctx);
 60	        });
 61	        app.get("/reservations/{id}/document", ctx -> {
 62	            ctx.attribute("roomDao", roomDao);
 63	            reservationHandler.getReceipt(ctx);
 64	        });
 65	
 66	        app.get("/messages", messageHandler::listMessages);
 67	
 68	        app.get("/reports/occupancy", reportHandler::occupancyReport);
 69	        app.get("/reports/revenue", reportHandler::revenueReport);
 70	
 71	        System.out.println("Server started on port " + port);
 72	    }
 73	
 74	    private static void initializeRooms(RoomDao roomDao) throws Exception {
 75	        Room[] rooms = {
 76	            new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90")),
 77	            new Room(102, RoomType.STANDARD, 2, new BigDecimal("249.90")),
 78	            new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90")),
 79	            new Room(202, RoomType.DELUXE, 3, new BigDecimal("389.90")),
 80	            new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90"))
 81	        };
 82	
 83	        for (Room room : rooms) {
 84	            if (roomDao.findByNumber(room.getNumber()) == null) {
 85	                roomDao.save(room);
 86	            }
 87	        }
 88	    }
 89	}
 90	package com.pousada.marealta.handler;
 91	
 92	import com.google.gson.JsonObject;
 93	import com.pousada.marealta.model.RatePlan;
 94	import com.pousada.marealta.model.ReceiptDto;
 95	import com.pousada.marealta.model.Reservation;
 96	import com.pousada.marealta.model.ReservationDto;
 97	import com.pousada.marealta.persistence.RoomDao;
 98	import com.pousada.marealta.service.MessageService;
 99	import com.pousada.marealta.service.ReservationService;
100	import io.javalin.http.Context;
101	
102	import java.math.BigDecimal;
103	import java.time.LocalDate;
104	import java.time.format.DateTimeParseException;
105	
106	public class ReservationHandler {
107	    private final ReservationService reservationService;
108	    private final MessageService messageService;
109	
110	    public ReservationHandler(ReservationService reservationService, MessageService messageService) {
111	        this.reservationService = reservationService;
112	        this.messageService = messageService;
113	    }
114	
115	    public void createReservation(Context ctx) {
116	        try {
117	            JsonObject body = ctx.bodyAsClass(JsonObject.class);
118	
119	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
120	                !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
121	                !body.has("guests") || !body.has("ratePlan")) {
122	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", "Missing required fields");
123	                return;
124	            }
125	
126	            int roomNumber = body.get("roomNumber").getAsInt();
127	            String guestName = body.get("guestName").getAsString();
128	            String guestEmail = body.get("guestEmail").getAsString();
129	            String guestCpf = body.get("guestCpf").getAsString();
130	            String checkInStr = body.get("checkIn").getAsString();
131	            String checkOutStr = body.get("checkOut").getAsString();
132	            int guests = body.get("guests").getAsInt();
133	            String ratePlanStr = body.get("ratePlan").getAsString();
134	            String companyCode = body.has("companyCode") ? body.get("companyCode").getAsString() : null;
135	
136	            try {
137	                LocalDate checkIn = LocalDate.parse(checkInStr);
138	                LocalDate checkOut = LocalDate.parse(checkOutStr);
139	
140	                RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
141	
142	                Reservation reservation = reservationService.createReservation(
143	                    roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode
144	                );
145	
146	                ctx.status(201).json(reservationToJson(reservation));
147	            } catch (IllegalArgumentException e) {
148	                String msg = e.getMessage();
149	                if ("ROOM_NOT_FOUND".equals(msg)) {
150	                    ErrorHandler.handle404(ctx, "ROOM_NOT_FOUND", "Room not found");
151	                } else if ("ROOM_UNAVAILABLE".equals(msg)) {
152	                    ErrorHandler.handle409(ctx, "ROOM_UNAVAILABLE", "Room is not available for the requested dates");
153	                } else if ("CAPACITY_EXCEEDED".equals(msg)) {
154	                    ErrorHandler.handle422(ctx, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
155	                } else if ("INVALID_REQUEST".equals(msg)) {
156	                    ErrorHandler.handle400(ctx, "INVALID_REQUEST", "Invalid rate plan or dates");
157	                } else {
158	                    ErrorHandler.handle400(ctx, "INVALID_REQUEST", msg);
159	                }
160	            } catch (DateTimeParseException e) {
161	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", "Invalid date format");
162	            }
163	        } catch (Exception e) {
164	            ErrorHandler.handleException(ctx, e);
165	        }
166	    }
167	
168	    public void getReservation(Context ctx) {
169	        try {
170	            long id = Long.parseLong(ctx.pathParam("id"));
171	            Reservation reservation = reservationService.getReservation(id);
172	            ctx.json(reservationToJson(reservation));
173	        } catch (IllegalArgumentException e) {
174	            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
175	                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
176	            } else {
177	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
178	            }
179	        } catch (Exception e) {
180	            ErrorHandler.handleException(ctx, e);
181	        }
182	    }
183	
184	    public void confirmReservation(Context ctx) {
185	        try {
186	            long id = Long.parseLong(ctx.pathParam("id"));
187	            Reservation reservation = reservationService.getReservation(id);
188	            BigDecimal amountPaid = reservation.getTotal();
189	
190	            try {
191	                JsonObject body = ctx.bodyAsClass(JsonObject.class);
192	                if (body != null && body.has("amountPaid")) {
193	                    amountPaid = new BigDecimal(body.get("amountPaid").getAsString());
194	                }
195	            } catch (Exception e) {
196	                // Body is optional, use total as default
197	            }
198	
199	            Reservation confirmedReservation = reservationService.confirmReservation(id, amountPaid);
200	            ctx.json(reservationToJson(confirmedReservation));
201	        } catch (IllegalArgumentException e) {
202	            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
203	                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
204	            } else if ("OPERATION_NOT_ALLOWED".equals(e.getMessage())) {
205	                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Cannot confirm reservation in current status");
206	            } else {
207	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
208	            }
209	        } catch (Exception e) {
210	            ErrorHandler.handleException(ctx, e);
211	        }
212	    }
213	
214	    public void checkIn(Context ctx) {
215	        try {
216	            long id = Long.parseLong(ctx.pathParam("id"));
217	            Reservation reservation = reservationService.checkIn(id);
218	            ctx.json(reservationToJson(reservation));
219	        } catch (IllegalArgumentException e) {
220	            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
221	                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
222	            } else if ("OPERATION_NOT_ALLOWED".equals(e.getMessage())) {
223	                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Cannot check in reservation in current status");
224	            } else {
225	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
226	            }
227	        } catch (Exception e) {
228	            ErrorHandler.handleException(ctx, e);
229	        }
230	    }
231	
232	    public void checkOut(Context ctx) {
233	        try {
234	            long id = Long.parseLong(ctx.pathParam("id"));
235	            Reservation reservation = reservationService.checkOut(id);
236	            RoomDao roomDao = (RoomDao) ctx.attribute("roomDao");
237	            String roomType = roomDao.findByNumber(reservation.getRoomNumber()).getType().name();
238	
239	            ReceiptDto receipt = new ReceiptDto(
240	                reservation.getId(),
241	                reservation.getGuestName(),
242	                reservation.getGuestCpf(),
243	                reservation.getRoomNumber(),
244	                roomType,
245	                reservation.getCheckIn(),
246	                reservation.getCheckOut(),
247	                reservation.getNights(),
248	                reservation.getSubtotal(),
249	                reservation.getDiscount(),
250	                reservation.getTotal()
251	            );
252	
253	            ctx.json(receipt);
254	        } catch (IllegalArgumentException e) {
255	            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
256	                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
257	            } else if ("OPERATION_NOT_ALLOWED".equals(e.getMessage())) {
258	                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Cannot check out reservation in current status");
259	            } else {
260	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
261	            }
262	        } catch (Exception e) {
263	            ErrorHandler.handleException(ctx, e);
264	        }
265	    }
266	
267	    public void cancelReservation(Context ctx) {
268	        try {
269	            long id = Long.parseLong(ctx.pathParam("id"));
270	            Reservation reservation = reservationService.cancelReservation(id);
271	            ctx.json(reservationToJson(reservation));
272	        } catch (IllegalArgumentException e) {
273	            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
274	                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
275	            } else if ("OPERATION_NOT_ALLOWED".equals(e.getMessage())) {
276	                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Cannot cancel reservation in current status");
277	            } else {
278	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
279	            }
280	        } catch (Exception e) {
281	            ErrorHandler.handleException(ctx, e);
282	        }
283	    }
284	
285	    public void getReceipt(Context ctx) {
286	        try {
287	            long id = Long.parseLong(ctx.pathParam("id"));
288	            Reservation reservation = reservationService.getReservation(id);
289	
290	            if (reservation.getStatus() == com.pousada.marealta.model.ReservationStatus.PENDING) {
291	                ErrorHandler.handle409(ctx, "OPERATION_NOT_ALLOWED", "Receipt is not available for pending reservations");
292	                return;
293	            }
294	
295	            RoomDao roomDao = (RoomDao) ctx.attribute("roomDao");
296	            String roomType = roomDao.findByNumber(reservation.getRoomNumber()).getType().name();
297	
298	            ReceiptDto receipt = new ReceiptDto(
299	                reservation.getId(),
300	                reservation.getGuestName(),
301	                reservation.getGuestCpf(),
302	                reservation.getRoomNumber(),
303	                roomType,
304	                reservation.getCheckIn(),
305	                reservation.getCheckOut(),
306	                reservation.getNights(),
307	                reservation.getSubtotal(),
308	                reservation.getDiscount(),
309	                reservation.getTotal()
310	            );
311	
312	            ctx.json(receipt);
313	        } catch (IllegalArgumentException e) {
314	            if ("RESERVATION_NOT_FOUND".equals(e.getMessage())) {
315	                ErrorHandler.handle404(ctx, "RESERVATION_NOT_FOUND", "Reservation not found");
316	            } else {
317	                ErrorHandler.handle400(ctx, "INVALID_REQUEST", e.getMessage());
318	            }
319	        } catch (Exception e) {
320	            ErrorHandler.handleException(ctx, e);
321	        }
322	    }
323	
324	    private Object reservationToJson(Reservation reservation) {
325	        return new ReservationDto(reservation);
326	    }
327	}

