 11	import java.math.BigDecimal;
 12	import java.time.LocalDate;
 13	import java.util.List;
 14	
 15	public class ReservationService {
 16	    private final ReservationDao reservationDao;
 17	    private final RoomDao roomDao;
 18	    private final PricingService pricingService;
 19	    private final MessageService messageService;
 20	
 21	    public ReservationService(ReservationDao reservationDao, RoomDao roomDao,
 22	                            PricingService pricingService, MessageService messageService) {
 23	        this.reservationDao = reservationDao;
 24	        this.roomDao = roomDao;
 25	        this.pricingService = pricingService;
 26	        this.messageService = messageService;
 27	    }
 28	
 29	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 30	                                        LocalDate checkIn, LocalDate checkOut, int guests,
 31	                                        RatePlan ratePlan, String companyCode) throws Exception {
 32	
 33	        Room room = roomDao.findByNumber(roomNumber);
 34	        if (room == null) {
 35	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
 36	        }
 37	
 38	        if (guests < 1 || guests > room.getCapacity()) {
 39	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
 40	        }
 41	
 42	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 43	            throw new IllegalArgumentException("INVALID_REQUEST");
 44	        }
 45	
 46	        validateRatePlan(ratePlan, checkIn, checkOut, companyCode);
 47	
 48	        List<Reservation> conflicts = reservationDao.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
 49	        if (!conflicts.isEmpty()) {
 50	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
 51	        }
 52	
 53	        PricingService.PriceCalculation pricing = pricingService.calculatePrice(room, checkIn, checkOut, ratePlan, companyCode);
 54	
 55	        Reservation reservation = new Reservation();
 56	        reservation.setRoomNumber(roomNumber);
 57	        reservation.setGuestName(guestName);
 58	        reservation.setGuestEmail(guestEmail);
 59	        reservation.setGuestCpf(guestCpf);
 60	        reservation.setCheckIn(checkIn);
 61	        reservation.setCheckOut(checkOut);
 62	        reservation.setGuests(guests);
 63	        reservation.setRatePlan(ratePlan);
 64	        reservation.setCompanyCode(companyCode);
 65	        reservation.setNights(pricing.nights);
 66	        reservation.setSubtotal(pricing.subtotal);
 67	        reservation.setDiscount(pricing.discount);
 68	        reservation.setTotal(pricing.total);
 69	        reservation.setStatus(ReservationStatus.PENDING);
 70	        reservation.setAmountPaid(BigDecimal.ZERO);
 71	
 72	        return reservationDao.save(reservation);
 73	    }
