 75	    public Reservation getReservation(long id) throws Exception {
 76	        Reservation reservation = reservationDao.findById(id);
 77	        if (reservation == null) {
 78	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
 79	        }
 80	        return reservation;
 81	    }
