 83	    public Reservation confirmReservation(long id, BigDecimal amountPaid) throws Exception {
 84	        Reservation reservation = getReservation(id);
 85	
 86	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 87	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
 88	        }
 89	
 90	        reservation.setStatus(ReservationStatus.CONFIRMED);
 91	        reservation.setAmountPaid(amountPaid);
 92	        reservationDao.update(reservation);
 93	
 94	        messageService.sendConfirmationEmail(reservation);
 95	
 96	        return reservation;
 97	    }
