 99	    public Reservation checkIn(long id) throws Exception {
100	        Reservation reservation = getReservation(id);
101	
102	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
103	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
104	        }
105	
106	        reservation.setStatus(ReservationStatus.CHECKED_IN);
107	        reservationDao.update(reservation);
108	
109	        return reservation;
110	    }
111	
112	    public Reservation checkOut(long id) throws Exception {
113	        Reservation reservation = getReservation(id);
114	
115	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
116	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
117	        }
118	
119	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
120	        reservationDao.update(reservation);
121	
122	        return reservation;
123	    }
124	
125	    public Reservation cancelReservation(long id) throws Exception {
126	        Reservation reservation = getReservation(id);
127	
128	        if (reservation.getStatus() != ReservationStatus.PENDING && reservation.getStatus() != ReservationStatus.CONFIRMED) {
129	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
130	        }
131	
132	        BigDecimal refund = PricingService.calculateRefund(reservation.getRatePlan(), reservation.getAmountPaid());
133	        refund = MoneyRounder.round(refund);
134	
135	        reservation.setStatus(ReservationStatus.CANCELLED);
136	        reservation.setRefund(refund);
137	        reservationDao.update(reservation);
138	
139	        return reservation;
140	    }
141	
142	    private void validateRatePlan(RatePlan ratePlan, LocalDate checkIn, LocalDate checkOut, String companyCode) {
143	        switch (ratePlan) {
144	            case CORPORATE:
145	                if (!"TECNOSUL".equals(companyCode) && !"AGROVALE".equals(companyCode) && !"FARMAVIDA".equals(companyCode)) {
146	                    throw new IllegalArgumentException("INVALID_REQUEST");
147	                }
148	                break;
149	
150	            case WEEKEND_PACKAGE:
151	                if (!PricingService.isWeekendPackageValid(checkIn, checkOut)) {
152	                    throw new IllegalArgumentException("INVALID_REQUEST");
153	                }
154	                break;
155	
156	            case LONG_STAY:
157	                long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
158	                if (nights < 7) {
159	                    throw new IllegalArgumentException("INVALID_REQUEST");
160	                }
161	                break;
162	
163	            default:
164	                break;
165	        }
166	    }
167	}
168	package com.pousada.marealta.service;
169	
170	import com.pousada.marealta.model.RatePlan;
171	import com.pousada.marealta.model.Room;
172	import com.pousada.marealta.model.RoomType;
173	import com.pousada.marealta.util.MoneyRounder;
174	import com.pousada.marealta.util.SeasonChecker;
175	
176	import java.math.BigDecimal;
177	import java.time.DayOfWeek;
178	import java.time.LocalDate;
179	
180	public class PricingService {
181	
182	    public static class PriceCalculation {
183	        public int nights;
184	        public BigDecimal subtotal;
185	        public BigDecimal discount;
186	        public BigDecimal total;
187	
188	        public PriceCalculation(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
189	            this.nights = nights;
190	            this.subtotal = subtotal;
191	            this.discount = discount;
192	            this.total = total;
193	        }
194	    }
195	
196	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
197	        return switch (ratePlan) {
198	            case STANDARD -> calculateStandard(room, checkIn, checkOut);
199	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut);
200	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
201	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
202	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
203	        };
204	    }
205	
206	    private PriceCalculation calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut) {
207	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
208	        BigDecimal subtotal = BigDecimal.ZERO;
209	
210	        for (int i = 0; i < nights; i++) {
211	            LocalDate night = checkIn.plusDays(i);
212	            BigDecimal nightPrice = room.getNightlyRate();
213	            if (SeasonChecker.isHighSeason(night)) {
214	                nightPrice = nightPrice.multiply(new BigDecimal("1.20"));
215	            }
216	            subtotal = subtotal.add(nightPrice);
217	        }
218	
219	        subtotal = MoneyRounder.round(subtotal);
220	        BigDecimal discount = BigDecimal.ZERO;
221	        BigDecimal total = subtotal;
222	
223	        return new PriceCalculation(nights, subtotal, discount, total);
224	    }
225	
226	    private PriceCalculation calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut) {
227	        PriceCalculation std = calculateStandard(room, checkIn, checkOut);
228	        BigDecimal discount = std.subtotal.multiply(new BigDecimal("0.15"));
229	        discount = MoneyRounder.round(discount);
230	        BigDecimal total = std.subtotal.subtract(discount);
231	        total = MoneyRounder.round(total);
232	        return new PriceCalculation(std.nights, std.subtotal, discount, total);
233	    }
234	
235	    private PriceCalculation calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
236	        PriceCalculation std = calculateStandard(room, checkIn, checkOut);
237	
238	        BigDecimal discountRate = switch (companyCode) {
239	            case "TECNOSUL" -> new BigDecimal("0.12");
240	            case "AGROVALE" -> new BigDecimal("0.18");
241	            case "FARMAVIDA" -> new BigDecimal("0.25");
242	            default -> BigDecimal.ZERO;
243	        };
244	
245	        BigDecimal discount = std.subtotal.multiply(discountRate);
246	        discount = MoneyRounder.round(discount);
247	        BigDecimal total = std.subtotal.subtract(discount);
248	        total = MoneyRounder.round(total);
249	
250	        return new PriceCalculation(std.nights, std.subtotal, discount, total);
251	    }
252	
253	    private PriceCalculation calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
254	        BigDecimal packagePrice = switch (room.getType()) {
255	            case STANDARD -> new BigDecimal("520.00");
256	            case DELUXE -> new BigDecimal("820.00");
257	            case SUITE -> new BigDecimal("1200.00");
258	        };
259	
260	        return new PriceCalculation(2, packagePrice, BigDecimal.ZERO, packagePrice);
261	    }
262	
263	    private PriceCalculation calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut) {
264	        PriceCalculation std = calculateStandard(room, checkIn, checkOut);
265	        BigDecimal discount = std.subtotal.multiply(new BigDecimal("0.10"));
266	        discount = MoneyRounder.round(discount);
267	        BigDecimal total = std.subtotal.subtract(discount);
268	        total = MoneyRounder.round(total);
269	        return new PriceCalculation(std.nights, std.subtotal, discount, total);
270	    }
271	
272	    public static boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
273	        if (java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut) != 2) {
274	            return false;
275	        }
276	
277	        DayOfWeek dayIn = checkIn.getDayOfWeek();
278	        DayOfWeek dayOut = checkOut.getDayOfWeek();
279	
280	        return dayIn == DayOfWeek.FRIDAY && dayOut == DayOfWeek.SUNDAY;
281	    }
282	
283	    public static BigDecimal calculateRefund(RatePlan ratePlan, BigDecimal amountPaid) {
284	        return switch (ratePlan) {
285	            case STANDARD -> amountPaid;
286	            case NON_REFUNDABLE -> BigDecimal.ZERO;
287	            case CORPORATE -> amountPaid;
288	            case WEEKEND_PACKAGE -> MoneyRounder.round(amountPaid.multiply(new BigDecimal("0.5")));
289	            case LONG_STAY -> amountPaid;
290	        };
291	    }
292	}
