 15	    private static HikariDataSource dataSource;
 16	
 17	    public static void init() throws SQLException {
 18	        String dbUrl = System.getenv("DB_URL");
 19	        String dbUser = System.getenv("DB_USER");
 20	        String dbPassword = System.getenv("DB_PASSWORD");
 21	
 22	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 23	            throw new IllegalStateException("DB_URL, DB_USER, and DB_PASSWORD environment variables must be set");
 24	        }
