 31	        config.setMinimumIdle(2);
 32	        config.setConnectionTimeout(30000);
 33	        config.setIdleTimeout(600000);
 34	        config.setMaxLifetime(1800000);
 35	
 36	        dataSource = new HikariDataSource(config);
 37	
 38	        createTables();
 39	        logger.info("Database initialized successfully");
 40	    }
 41	
 42	    private static void createTables() throws SQLException {
 43	        try (Connection conn = dataSource.getConnection();
 44	             Statement stmt = conn.createStatement()) {
 45	
 46	            String[] createTableStatements = {
 47	                "CREATE TABLE IF NOT EXISTS rooms (" +
 48	                "    number INT PRIMARY KEY," +
 49	                "    type VARCHAR(20) NOT NULL," +
 50	                "    capacity INT NOT NULL," +
 51	                "    nightly_rate NUMERIC(10, 2) NOT NULL" +
 52	                ")",
 53	
 54	                "CREATE TABLE IF NOT EXISTS reservations (" +
 55	                "    id SERIAL PRIMARY KEY," +
 56	                "    room_number INT NOT NULL REFERENCES rooms(number)," +
 57	                "    guest_name VARCHAR(255) NOT NULL," +
 58	                "    guest_email VARCHAR(255) NOT NULL," +
 59	                "    guest_cpf VARCHAR(20) NOT NULL," +
 60	                "    check_in DATE NOT NULL," +
 61	                "    check_out DATE NOT NULL," +
 62	                "    guests INT NOT NULL," +
 63	                "    rate_plan VARCHAR(50) NOT NULL," +
 64	                "    company_code VARCHAR(50)," +
 65	                "    nights INT NOT NULL," +
 66	                "    subtotal NUMERIC(10, 2) NOT NULL," +
 67	                "    discount NUMERIC(10, 2) NOT NULL," +
 68	                "    total NUMERIC(10, 2) NOT NULL," +
 69	                "    status VARCHAR(50) NOT NULL," +
 70	                "    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0," +
 71	                "    refund NUMERIC(10, 2)" +
 72	                ")",
 73	
 74	                "CREATE TABLE IF NOT EXISTS messages (" +
 75	                "    id SERIAL PRIMARY KEY," +
 76	                "    channel VARCHAR(50) NOT NULL," +
 77	                "    to_address VARCHAR(255) NOT NULL," +
 78	                "    subject VARCHAR(500)," +
 79	                "    body TEXT" +
 80	                ")"
 81	            };
 82	
 83	            for (String sql : createTableStatements) {
 84	                stmt.execute(sql);
 85	            }
 86	
 87	            logger.info("Tables created successfully");
 88	        }
 89	    }
