 21	    public String generateOccupancyReport(LocalDate date) throws Exception {
 22	        List<Reservation> reservations = reservationDao.findByDateAndStatus(date);
 23	
 24	        StringBuilder csv = new StringBuilder();
 25	        csv.append("room,type,reservation,check_in,check_out\n");
 26	
 27	        for (Reservation res : reservations) {
 28	            String type = roomDao.findByNumber(res.getRoomNumber()).getType().name();
 29	            csv.append(String.format("%d,%s,%d,%s,%s\n",
 30	                res.getRoomNumber(),
 31	                type,
 32	                res.getId(),
 33	                formatDate(res.getCheckIn()),
 34	                formatDate(res.getCheckOut())
 35	            ));
 36	        }
 37	
 38	        int occupiedRooms = (int) reservations.stream()
 39	            .map(Reservation::getRoomNumber)
 40	            .distinct()
 41	            .count();
 42	
 43	        csv.append(String.format("total,%d/5\n", occupiedRooms));
 44	
 45	        return csv.toString();
 46	    }
