 50	
 51	        StringBuilder csv = new StringBuilder();
 52	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 53	
 54	        BigDecimal total = BigDecimal.ZERO;
 55	
 56	        for (Reservation res : reservations) {
 57	            BigDecimal amount = res.getAmountPaid();
 58	            if (res.getRefund() != null) {
 59	                amount = amount.subtract(res.getRefund());
 60	            }
 61	
 62	            csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
 63	                res.getId(),
 64	                res.getRoomNumber(),
 65	                formatDate(res.getCheckIn()),
 66	                formatDate(res.getCheckOut()),
 67	                res.getStatus().name(),
 68	                formatMoney(amount)
 69	            ));
 70	
 71	            total = total.add(amount);
 72	        }
