 96	public class MessageService {
 97	    private final MessageDao messageDao;
 98	    private final RoomDao roomDao;
 99	
100	    public MessageService(MessageDao messageDao, RoomDao roomDao) {
101	        this.messageDao = messageDao;
102	        this.roomDao = roomDao;
103	    }
104	
105	    public void sendConfirmationEmail(Reservation reservation) throws SQLException {
106	        String guestName = reservation.getGuestName();
107	        String roomType = roomDao.findByNumber(reservation.getRoomNumber()).getType().name();
108	
109	        String subject = "Reserva confirmada - Pousada Maré Alta";
110	
111	        String receipt = formatReceipt(reservation, roomType);
112	
113	        String body = String.format(
114	            "Olá, %s!\n\n" +
115	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
116	            "%s\n\n" +
117	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
118	            "Até breve!",
119	            guestName,
120	            receipt
121	        );
122	
123	        Message message = new Message("EMAIL", reservation.getGuestEmail(), subject, body);
124	        messageDao.save(message);
125	    }
126	
127	    private String formatReceipt(Reservation reservation, String roomType) {
128	        StringBuilder sb = new StringBuilder();
129	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
130	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
131	        sb.append(String.format("Quarto: %d (%s)\n", reservation.getRoomNumber(), roomType));
132	
133	        String nightsLabel = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
134	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
135	            formatDate(reservation.getCheckIn()),
136	            formatDate(reservation.getCheckOut()),
137	            nightsLabel));
138	
139	        sb.append(String.format("Diárias: R$ %s\n", formatMoney(reservation.getSubtotal())));
140	
141	        if (reservation.getDiscount().signum() > 0) {
142	            sb.append(String.format("Desconto: R$ %s\n", formatMoney(reservation.getDiscount())));
143	        }
144	
145	        sb.append(String.format("Total: R$ %s", formatMoney(reservation.getTotal())));
146	
147	        return sb.toString();
148	    }
149	
150	    public String getReceiptAsString(Reservation reservation, String roomType) {
151	        return formatReceipt(reservation, roomType);
152	    }
153	
154	    private String formatDate(java.time.LocalDate date) {
155	        return String.format("%02d/%02d/%d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
156	    }
157	
158	    private String formatMoney(java.math.BigDecimal value) {
159	        return String.format("%.2f", value).replace(".", ",");
160	    }
161	
162	    private String formatCpf(String cpf) {
163	        if (cpf == null || cpf.length() != 11) {
164	            return cpf;
165	        }
166	        return String.format("%s.%s.%s-%s",
167	            cpf.substring(0, 3),
168	            cpf.substring(3, 6),
169	            cpf.substring(6, 9),
170	            cpf.substring(9));
171	    }
172	}
