180	public class ErrorHandler {
181	    public static void handleException(Context ctx, Exception e) {
182	        String message = e.getMessage() != null ? e.getMessage() : "Internal server error";
183	
184	        Map<Integer, String> errorMap = new HashMap<>();
185	        errorMap.put(400, "INVALID_REQUEST");
186	        errorMap.put(404, "NOT_FOUND");
187	        errorMap.put(409, "CONFLICT");
188	        errorMap.put(422, "UNPROCESSABLE_ENTITY");
189	
190	        int status = 400;
191	        String errorCode = "INVALID_REQUEST";
192	
193	        if (message.equals("ROOM_NOT_FOUND")) {
194	            status = 404;
195	            errorCode = "ROOM_NOT_FOUND";
196	        } else if (message.equals("RESERVATION_NOT_FOUND")) {
197	            status = 404;
198	            errorCode = "RESERVATION_NOT_FOUND";
199	        } else if (message.equals("ROOM_UNAVAILABLE")) {
200	            status = 409;
201	            errorCode = "ROOM_UNAVAILABLE";
202	        } else if (message.equals("OPERATION_NOT_ALLOWED")) {
