  12	public class GsonConfig {
  13	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE;
  14	
  15	    public static Gson createGson() {
  16	        return new GsonBuilder()
  17	            .registerTypeAdapter(LocalDate.class, (JsonSerializer<LocalDate>) (src, typeOfSrc, context) ->
  18	                context.serialize(src.format(DATE_FORMATTER)))
  19	            .registerTypeAdapter(LocalDate.class, (JsonDeserializer<LocalDate>) (json, typeOfT, context) ->
  20	                LocalDate.parse(json.getAsString(), DATE_FORMATTER))
  21	            .registerTypeAdapter(BigDecimal.class, (JsonSerializer<BigDecimal>) (src, typeOfSrc, context) -> {
  22	                if (src == null) return context.serialize(null);
  23	                return context.serialize(src.setScale(2, java.math.RoundingMode.HALF_EVEN).doubleValue());
  24	            })
  25	            .registerTypeAdapter(BigDecimal.class, (JsonDeserializer<BigDecimal>) (json, typeOfT, context) ->
  26	                new BigDecimal(json.getAsString()))
  27	            .create();
  28	    }
  29	}
